    sampleAnswer: `#[external(v0)]
fn transfer(ref self: ContractState, to: ContractAddress, amount: u256) {
    let caller = get_caller_address();

    // OPTIMISED: read once, cache in local variable — 2,000 gas
    let caller_balance = self.balances.entry(caller).read();
    assert(caller_balance >= amount, 'Insufficient balance');
    self.balances.entry(caller).write(caller_balance - amount);

    // Recipient balance — also read once
    let recipient_balance = self.balances.entry(to).read();
    self.balances.entry(to).write(recipient_balance + amount);

    // Event emitted — 200 gas, provides history for Voyager and frontends
    self.emit(Transfer { from: caller, to, value: amount });
}`,
