    sampleAnswer: `#[external(v0)]
fn stake_and_supply(ref self: ContractState, amount: u256) {
    let caller = get_caller_address();
    let this = starknet::get_contract_address();

    // CHECK: validate all conditions first
    assert(!self.is_paused.read(), 'Protocol paused');
    assert(amount > 0_u256, 'Amount must be positive');
    let current_staked = self.staked.entry(caller).read();

    // EFFECT: update state before any external calls
    self.staked.entry(caller).write(current_staked + amount);
    self.total_staked.write(self.total_staked.read() + amount);

    // INTERACT: external calls after our state is consistent
    // If either reverts, EFFECT above is also undone — atomicity
    let strk = IERC20Dispatcher { contract_address: self.strk_token.read() };
    let ok = strk.transfer_from(caller, this, amount);
    assert(ok, 'STRK transfer failed');

    ILendingPoolDispatcher { contract_address: self.lending_pool.read() }
        .deposit(amount);

    // EMIT
    self.emit(StakedAndSupplied {
        staker: caller,
        amount,
        block_number: get_block_number(),
    });
}`,
